export function FocusTrap({
  title = "{{title}}",
  trapped = {{trapped}},
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  return (
    <div style={{ width: 320, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ padding: 14, borderRadius: 10, background: "#24143010", color: "#241430aa", fontSize: 12, marginBottom: 12 }}>Background page (inert while dialog is open)</div>
      <div role="dialog" aria-modal="true" style={{ padding: 16, background: "#FAF7F2", boxShadow: "0 12px 32px rgba(36,20,48,.22)", borderRadius: radius }}>
        <p style={{ margin: "0 0 12px", fontWeight: 700 }}>{title}</p>
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" style={{ padding: "9px 16px", borderRadius: 7, border: "1.5px solid #24143033", background: "transparent", cursor: "pointer" }}>Cancel</button>
          <button type="button" style={{ padding: "9px 16px", borderRadius: 7, border: "1.5px solid " + accent, background: accent, fontWeight: 600, cursor: "pointer" }}>Delete</button>
        </div>
        {trapped
          ? <p style={{ margin: "12px 0 0", fontSize: 12, color: "#1a7a44" }}>&#8635; Tab from Delete wraps back to Cancel</p>
          : <p style={{ margin: "12px 0 0", fontSize: 12, color: "#b3261e" }}>&#8594; Tab from Delete escapes to the page behind</p>}
      </div>
    </div>
  );
}
